public int findLargestSubstring(List<String> strings) {
    // Initialize a list to hold the largest string and its inverse
    List<String> largestSubstrings = new ArrayList<>();

    // Loop through each string in the input list
    for (String str : strings) {
        // Get the length of the current string
        int strLen = str.length();

        // Loop through each substring of the current string
        for (int i = 0; i < strLen; i++) {
            // Get the substring of the current string starting from index i
            String substr = str.substring(i);

            // Check if the substring is equal to its inverse
            if (substr.equals(new StringBuilder(substr).reverse().toString())) {
                // If so, add the substring to the list of largest substrings
                largestSubstrings.add(substr);

                // Break out of the inner loop to move on to the next string
                break;
            }
        }
    }

    // Return the length of the largest substring(s) found
    return largestSubstrings.size();
}

public int findLargestSubstring(List<String> strings) {

  // Initialize a hash map to store the counts of each string
  Map<String, Integer> map = new HashMap<>();
  for (String s : strings) {
    map.put(s, 0);
  }

  // Iterate over each string and update its inverse in the hash map
  for (String s : strings) {
    String inverse = inverseString(s);
    if (!map.containsKey(inverse)) {
      map.put(inverse, 0);
    }
  }

  // Iterate over each string again and find the largest substring
  int largestSubstring = 0;
  for (String s : strings) {
    int count = 1;
    for (int i = 1; i < s.length(); i++) {
      String prefix = s.substring(0, i);
      String suffix = s.substring(i);
      if (map.containsKey(prefix) && map.containsKey(suffix)) {
        count = Math.max(count, map.get(prefix) + map.get(suffix));
      }
    }
    largestSubstring = Math.max(largestSubstring, count);
  }

  return largestSubstring;
}

