    if (grid.length == 0) {
        return 0;
    }

    int deposits = 0;
    Set<Integer> visited = new HashSet<>();

    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@' && !visited.contains(i * grid[i].length + j)) {
                dfs(grid, i, j, visited);
                deposits++;
            }
        }
    }

    return deposits;
}

