public static int maxRegions(int N) {
    if (N <= 0) {
        return 0;
    }
    int maxRegions = 1;
    int currentRegion = 1;
    for (int i = 1; i <= N; i++) {
        currentRegion = currentRegion * (i + 1) / (i + 2);
        maxRegions = Math.max(maxRegions, currentRegion);
    }
    return maxRegions;
}

public static int maxRegions(int N) {
    if (N == 1) {
        return 2;
    }
    return 2 * (N - 1) + maxRegions(N - 1);
}

