public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Initialize a set to store visited n-tersections
  Set<int[]> visited = new HashSet<>();

  // Create a queue to perform BFS
  Queue<int[]> queue = new LinkedList<>();

  // Add the starting n-tersection to the queue and visited set
  queue.add(start);
  visited.add(start);

  // Loop until the queue is empty
  while (!queue.isEmpty()) {
    // Remove the first n-tersection from the queue
    int[] current = queue.remove();

    // Check if this n-tersection is the ending n-tersection
    if (current[0] == end[0] && current[1] == end[1]) {
      return "can be travelled";
    }

    // Loop through all n-tersections adjacent to the current n-tersection
    for (int i = 0; i < n; i++) {
      // Get the coordinates of the adjacent n-tersection
      int[] adjacent = {current[0] + paths[i][0], current[1] + paths[i][1]};

      // Check if this n-tersection is already visited or out of bounds
      if (visited.contains(adjacent) || !isInBounds(adjacent)) {
        continue;
      }

      // Add the adjacent n-tersection to the queue and visited set
      queue.add(adjacent);
      visited.add(adjacent);
    }
  }

  return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a visited array to keep track of the n-tersections that have been visited
    boolean[] visited = new boolean[n];
    // Mark the starting n-tersection as visited
    visited[start[0] * n + start[1]] = true;
    // Initialize a queue to perform BFS
    Queue<int[]> queue = new LinkedList<>();
    // Add the starting n-tersection to the queue
    queue.add(start);

    while (!queue.isEmpty()) {
        // Dequeue the next n-tersection to visit
        int[] current = queue.remove();
        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }
        // Check each path leading from the current n-tersection
        for (int[] path : paths) {
            // If the path leads to an unvisited n-tersection, mark it as visited and add it to the queue
            if (!visited[path[0] * n + path[1]]) {
                visited[path[0] * n + path[1]] = true;
                queue.add(path);
            }
        }
    }

    // If the ending n-tersection was not found, return "cannot be travelled"
    return "cannot be travelled";
}

