    queue.add(start);
    visited.add(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the first n-tersection in the queue
        int current = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        // loop through all adjacent n-tersections of the current n-tersection
        for (int[] path : paths) {
            // If the adjacent n-tersection is not visited, add it to the queue and visited set
            if (!visited.contains(path[0]) && !visited.contains(path[1])) {
                queue.add(path[0]);
                visited.add(path[0]);
                queue.add(path[1]);
                visited.add(path[1]);
            }
        }
    }

    // If the queue is empty and the ending n-tersection has not been visited, return "cannot be travelled"
    return "cannot be travelled";
}

