public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a graph with n nodes and edges from paths
    Graph graph = new Graph(n);
    for (int[] path : paths) {
        graph.addEdge(path[0], path[1]);
    }

    // Perform Breadth-First Search (BFS) from start node to end node
    Queue<Integer> queue = new LinkedList<>();
    queue.add(start);
    boolean[] visited = new boolean[n];
    visited[start] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == end) {
            return "can be travelled";
        }
        for (int neighbor : graph.getNeighbors(current)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

