public boolean canArrange(int[] arr, int k) {
    // base case: if the array length is odd, it cannot be divided into pairs
    if (arr.length % 2 != 0) {
      return false;
    }

    // create a map to keep track of the counts of each element in the array
    Map<Integer, Integer> countMap = new HashMap<>();
    for (int element : arr) {
      if (countMap.containsKey(element)) {
        countMap.put(element, countMap.get(element) + 1);
      } else {
        countMap.put(element, 1);
      }
    }

    // iterate through the map and check if the sum of each pair is divisible by k
    for (Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
      int element = entry.getKey();
      int count = entry.getValue();

      // if the count is odd, it cannot be divided into pairs
      if (count % 2 != 0) {
        return false;
      }

      // check if the sum of the pair is divisible by k
      int pairSum = element * count / 2;
      if (pairSum % k != 0) {
        return false;
      }
    }

    return true;
  }

