    PriorityQueue<Node> pq = new PriorityQueue<>();

    // Add node 0 to the priority queue with a time of 0
    pq.add(new Node(0, 0));

    // Loop until the priority queue is empty
    while (!pq.isEmpty()) {
        // Get the node with the minimum time from the priority queue
        Node node = pq.poll();

        // If the node has not been visited, mark it as visited and add its neighbors to the priority queue
        if (!node.visited) {
            node.visited = true;
            for (int i = 0; i < edges.length; i++) {
                int neighbor = edges[node.id][i];
                if (neighbor != -1 && !nodes[neighbor].visited) {
                    pq.add(new Node(neighbor, node.time + 1));
                }
            }
        }
    }

