    // Initialize a Graph from the input edges
    Graph graph = new Graph(n, edges);

    // Perform Breadth-First Search (BFS) from node 0
    int[] distances = new int[n];
    for (int i = 0; i < n; i++) {
        distances[i] = -1;
    }
    distances[0] = 0;

    int[] prev = new int[n];
    Arrays.fill(prev, -1);

    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);

    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int neighbor : graph.neighbors(node)) {
            if (distances[neighbor] == -1) {
                distances[neighbor] = distances[node] + 1;
                prev[neighbor] = node;
                queue.offer(neighbor);
            }
        }
    }

    // Find the deepest node with an apple
    int maxDepth = -1;
    int deepestNodeWithApple = -1;
    for (int i = 0; i < n; i++) {
        if (hasApple[i] && distances[i] > maxDepth) {
            maxDepth = distances[i];
            deepestNodeWithApple = i;
        }
    }

    // Compute the minimum time required to collect all apples and return to node 0
    int minTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i] && i != deepestNodeWithApple && distances[i] > maxDepth) {
            minTime += distances[i] - maxDepth;
        }
    }

    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }

    // Build the graph with the given edges
    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    // Initialize the minimum time required to collect all the apples
    int minTime = 0;

    // Initialize the set of nodes that have apples
    Set<Integer> nodesWithApples = new HashSet<>();
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            nodesWithApples.add(i);
        }
    }

    // Initialize the set of nodes that have been visited
    Set<Integer> visited = new HashSet<>();

    // Perform a DFS from node 0 to collect all the apples
    dfs(graph, nodesWithApples, visited, 0, minTime);

    // Return the minimum time required to collect all the apples
    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize tree nodes
    Node[] tree = new Node[n];
    for (int i = 0; i < n; i++) {
        tree[i] = new Node(i);
    }

    // Build tree
    for (int[] edge : edges) {
        tree[edge[0]].edges.add(new Edge(edge[1], hasApple[edge[1]]));
    }

    // DFS
    int time = 0;
    Stack<Node> stack = new Stack<>();
    stack.push(tree[0]);
    while (!stack.isEmpty()) {
        Node current = stack.pop();
        if (current.label == 0) {
            return time;
        }
        for (Edge edge : current.edges) {
            if (!edge.visited && hasApple[edge.destination]) {
                time += 1;
                edge.visited = true;
                stack.push(tree[edge.destination]);
            }
        }
    }
    return time;
}

private void postorderTraversal(int currNode, boolean[] hasApple, int[][] edges, int[][] minTime) {
    // If the current node has no children, set the minimum time required to collect all apples and return to node 0 from the current node to 0.
    if (edges[currNode].length == 0) {
        minTime[currNode][0] = 0;
        minTime[currNode][1] = 0;
        return;
    }

    // Traverse the children of the current node.
    for (int child : edges[currNode]) {
        // Recursively call the postorder traversal on the child node.
        postorderTraversal(child, hasApple, edges, minTime);

        // Update the minimum time required to collect all apples and return to node 0 from the current node based on the minimum time required to collect all apples and return to node 0 from the child node.
        minTime[currNode][0] = Math.min(minTime[currNode][0], minTime[child][0]);
        minTime[currNode][1] = Math.min(minTime[currNode][1], minTime[child][1]);
    }

    // If the current node has an apple, update the minimum time required to collect all apples and return to node 0 from the current node based on the minimum time required to collect all apples and return to node 0 from the child nodes.
    if (hasApple[currNode]) {
        minTime[currNode][0] = Math.min(minTime[currNode][0], minTime[currNode][1] + 1);
        minTime[currNode][1] = Math.min(minTime[currNode][1], minTime[currNode][0] + 1);
    }
}

