    while (result.length() < s.length()) {
        int smallest = getSmallestCharacter(s);
        int largest = getLargestCharacter(s);
        result.append((char) smallest);
        result.append((char) largest);
        s = s.replaceAll(String.valueOf((char) smallest), "");
        s = s.replaceAll(String.valueOf((char) largest), "");
    }
    return result.toString();
}

