public int minCostClimbingStairs(int[] cost) {
    int cost1 = 0;
    int cost2 = 0;
    for (int i = 0; i < cost.length; i++) {
        if (i == 0) {
            cost1 = 0;
            cost2 = 0;
        } else {
            if (i == 1) {
                cost1 = cost[i] + cost[i - 1];
                cost2 = cost[i] + cost[i - 2];
            } else {
                cost1 = Math.min(cost1, cost2) + cost[i];
                cost2 = cost1;
            }
        }
    }
    return Math.min(cost1, cost2);
}

