public boolean hasAllCodes(String s, int k) {
        int n = s.length();
        int totalCombinations = (int)Math.pow(2, k);
        boolean[] found = new boolean[totalCombinations];
        for (int i = 0; i < n - k + 1; i++) {
            int binaryString = Integer.parseInt(s.substring(i, i + k), 2);
            if (binaryString < totalCombinations) {
                found[binaryString] = true;
            }
        }
        for (int i = 0; i < totalCombinations; i++) {
            if (!found[i]) {
                return false;
            }
        }
        return true;
    }

public static boolean hasAllCodes(String s, int k) {
        // Initialize a set to store all binary strings of length k
        Set<String> binaryStrings = new HashSet<>();

        // Iterate over the length of the input string
        for (int i = 0; i <= s.length() - k; i++) {
            // Get the substring of length k starting from the current index
            String substring = s.substring(i, i + k);

            // If the substring is of length k and contains only '0's and '1's, add it to the set
            if (substring.length() == k && substring.matches("[01]+")) {
                binaryStrings.add(substring);
            }
        }

        // Return true if the set size is 2^k, false otherwise
        return binaryStrings.size() == (int) Math.pow(2, k);
    }

public boolean hasAllCodes(String s, int k) {
  // Initialize a set to store the binary strings of length k
  Set<String> subs = new HashSet<>();

  // Loop through the string s and extract all binary strings of length k
  for (int i = 0; i <= s.length() - k; i++) {
    String sub = s.substring(i, i + k);
    if (sub.length() == k) {
