        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 0) continue;

            int length = 1;
            while (i + 1 < m && mat[i + 1][j] == 1) {
                length++;
                i++;
            }

            while (j + 1 < n && mat[i][j + 1] == 1) {
