public static int longestLine(int[][] mat) {
    int[][] directions = {{1, 1}, {1, 0}, {-1, 1}, {-1, 0}, {0, 1}, {0, -1}, {1, 1}, {-1, -1}};
    int m = mat.length, n = mat[0].length;
    int[][] dp = new int[m][n];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                for (int[] dir : directions) {
                    dp[i][j] = Math.max(dp[i][j], dp[i - dir[0]][j - dir[1]] + 1);
                }
            }
        }
    }

    return dp[m - 1][n - 1];
}

