    if (points.length != 3) {
        return false;
    }

    // Check if the points form a right triangle
    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];
    int dx1 = p2[0] - p1[0];
    int dy1 = p2[1] - p1[1];
    int dx2 = p3[0] - p2[0];
    int dy2 = p3[1] - p2[1];
    return (dx1 * dy2 - dy1 * dx2) != 0;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Check if the points are aligned vertically or horizontally
    if (points[0][0] == points[1][0] && points[1][0] == points[2][0]) {
        return false;
    }
    if (points[0][1] == points[1][1] && points[1][1] == points[2][1]) {
        return false;
    }
    // Check if the points form a triangle
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];
    if (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2) == 0) {
        return false;
    }
    // Check if the points have the same x-coordinate or same y-coordinate
    if (x1 == x2 || x1 == x3 || x2 == x3 || y1 == y2 || y1 == y3 || y2 == y3) {
        return false;
    }
    return true;
}

public static boolean isBoomerang(int[][] points) {
    // Check inputs
    if (points == null || points.length != 3) {
        return false;
    }

    // Calculate slopes: m1 = (y2-y1)/(x2-x1), m2 = (y3-y2)/(x3-x2)
    int[] x = points[0][0] - points[1][0];
    int[] y = points[0][1] - points[1][1];
    double m1 = (double) y[0] / x[0];
    y = points[1][0] - points[2][0];
    x = points[1][1] - points[2][1];
    double m2 = (double) y[0] / x[0];

    // Check if slopes are equal and non-zero
    if (m1 == m2) {
        return false;
    }

    // Calculate third point coordinates (x3, y3)
    int[] x3 = points[1][0] + (int) ((m1 * (points[2][0] - points[1][0])) / (m1 - m2));
    int[] y3 = points[1][1] + (int) ((m1 * (points[2][1] - points[1][1])) / (m1 - m2));

    // Check if (x3, y3) is on the line segment (x1, y1) to (x2, y2)
    int[] x1 = points[0][0] - points[1][0];
    int[] y1 = points[0][1] - points[1][1];
    int[] x2 = points[1][0] - points[2][0];
    int[] y2 = points[1][1] - points[2][1];
    return (checkSE(!(Math.signum(x1[0]) == Math.signum(x2[0]) || Math.signum(y1[0]) == Math.signum(y2[0])) || !(x1[0] == y1[0]) || !(x2[0] == y2[0])) // (x3, y3) is not on the line segment
    return true;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The index must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int p2 = 0, p3 = 0, p5 = 0;
    int factor2 = 2, factor3 = 3, factor5 = 5;

    for (int i = 1; i < n; i++) {
        int min = Math.min(factor2, Math.min(factor3, factor5));
        uglyNumbers[i] = min;
        if (min == factor2) {
            p2++;
            factor2 = uglyNumbers[p2] * 2;
        }
        if (min == factor3) {
            p3++;
            factor3 = uglyNumbers[p3] * 3;
        }
        if (min == factor5) {
            p5++;
            factor5 = uglyNumbers[p5] * 5;
        }
    }

    return uglyNumbers[n - 1];
}

