public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i = 0;
    int nextUglyNumber = 1;
    boolean foundAllUglyNumbers = false;
    while (!foundAllUglyNumbers) {
        boolean divisible = false;
        for (int j = 2; j <= Math.sqrt(nextUglyNumber) && !divisible; j++) {
            if (nextUglyNumber % j == 0) {
                divisible = true;
                break;
            }
        }
        if (!divisible) {
            uglyNumbers[i] = nextUglyNumber++;
            i++;
            if (i == n) {
                foundAllUglyNumbers = true;
            }
        }
    }
    return uglyNumbers[n - 1];
}

