public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
      return 0;
    }
    int current = 1;
    int max = 1;
    for (int i = 1; i < s.length(); i++) {
      if (s.charAt(i) == s.charAt(i - 1)) {
        current++;
        if (current > max) {
          max = current;
        }
      } else {
        current = 1;
      }
    }
    return max;
  }

public static int calculateEnergy(String s) {
    if (s.isEmpty()) {
        return 0;
    }
    int energy = 0;
    char previousChar = s.charAt(0);
    int currentLength = 1;
    for (int i = 1; i < s.length(); i++) {
        char currentChar = s.charAt(i);
        if (currentChar == previousChar) {
            currentLength++;
        } else {
            energy = Math.max(energy, currentLength);
            previousChar = currentChar;
            currentLength = 1;
        }
    }
    energy = Math.max(energy, currentLength);
    return energy;
}

