public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            result.add(i);
        }
        Collections.sort(result, (a, b) -> String.valueOf(a).compareTo(String.valueOf(b)));
        return result;
    }

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    result.sort((a, b) -> (a < b ? a.toString().compareTo(b.toString()) : 0));
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> list = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        list.add(i);
    }
    Collections.sort(list, new Comparator<Integer>() {
        @Override
        public int compare(Integer o1, Integer o2) {
            return Integer.toString(o1).compareTo(Integer.toString(o2));
        }
    });
    return list;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        int current = i;
        while (current > 0) {
            result.add(current % 10);
            current /= 10;
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<Integer>();

    for (int i = 1; i <= n; i++) {
        int val = i;
        for (int j = 10; j > 0; j /= 10) {
            int digit = j * val % 10;
            if (digit > 0) {
                result.add(digit);
                break;
            }
        }
    }

    return result;
}

public static int calculateUniqueSum(int[] nums) {
        Set<Integer> seen = new HashSet<>();
        int sum = 0;
        for (int num : nums) {
            if (!seen.contains(num)) {
                sum += num;
                seen.add(num);
            }
        }
        return sum;
    }

