public static int minPerfectSquareSum(int n) {
    // Initialize a HashMap to store the perfect square numbers
    Map<Integer, Integer> squares = new HashMap<>();
    squares.put(1, 1);

    // Loop until the target number is reached
    while (n > 0) {
        // Find the largest perfect square number that is less than or equal to the target number
        int perfectSquare = findLargestPerfectSquare(n, squares);

        // Update the target number and the HashMap
        n -= perfectSquare;
        squares.put(perfectSquare, perfectSquare + squares.getOrDefault(perfectSquare, 0));
    }

    // Return the minimum number of perfect square numbers
    return squares.size();
}

public static int minPerfectSquareSum(int n) {
    int minSquares = Integer.MAX_VALUE;
    for (int i = 1; i <= n / 2; i++) {
        int squares = 0;
        int remainder = n - i * i;
        for (int j = 1; j <= remainder / j; j++) {
            squares++;
            remainder -= j * j;
        }
        if (remainder == 0) {
            minSquares = Math.min(minSquares, squares + 1);
        }
    }
    return minSquares == Integer.MAX_VALUE ? -1 : minSquares;
}

public static int minPerfectSquareSum(int n) {
    /*
     * Initialize a list to store the perfect square numbers.
     */
    List<Integer> perfectSquares = new ArrayList<>();

    /*
     * Iterate from 1 to sqrt(n) and calculate the square of each number.
     * If the square is less than or equal to n, add it to the list.
     */
    for (int i = 1; i * i <= n; i++) {
        int square = i * i;
        if (square <= n) {
            perfectSquares.add(square);
        }
    }

    /*
     * Initialize a variable to store the minimum number of perfect square numbers.
     */
    int minPerfectSquareSum = n;

    /*
     * Iterate through the list of perfect square numbers and calculate the sum of each sublist
     * (i.e., each sublist contains consecutive perfect square numbers).
     * If the sum of the sublist is equal to n, update the minimum number of perfect square numbers.
     */
    for (int i = 0; i < perfectSquares.size(); i++) {
        int sum = 0;
        for (int j = i; j < perfectSquares.size(); j++) {
            sum += perfectSquares.get(j);
            if (sum == n) {
                minPerfectSquareSum = Math.min(minPerfectSquareSum, j - i + 1);
                break;
            }
        }
    }

    return minPerfectSquareSum;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        count++;
        n -= root * root;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int perfectSquares = 0;
    while (n > 0) {
        perfectSquares++;
        n -= (int) Math.sqrt(n);
    }
    return perfectSquares;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder sb = new StringBuilder();

    for (String word : words) {
        sb.append(new StringBuilder(word).reverse().toString());
        sb.append(" ");
    }

    return sb.toString().trim();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder builder = new StringBuilder();
    for (String word : words) {
        builder.append(new StringBuilder(word).reverse().toString());
        builder.append(" ");
    }
    return builder.toString().trim();
}

public static String reverseWords(String s) {
    // split the input string into an array of words
    String[] words = s.split(" ");

    // initialize a new string to store the reversed words
    String reversed = "";

    // iterate through the words in the input string
    for (String word : words) {
        // reverse the current word
        String reversedWord = new StringBuilder(word).reverse().toString();

        // append the reversed word to the output string
        reversed += " " + reversedWord;
    }

    // return the output string with the reversed words
    return reversed.trim();
}

public static String reverseWords(String s) {
    StringBuilder result = new StringBuilder();
    String[] words = s.split(" ");
    for (String word : words) {
        result.append(reverse(word));
        result.append(" ");
    }
    return result.toString().trim();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    String result = "";
    for (int i = words.length - 1; i >= 0; i--) {
        result += words[i];
        if (i > 0) {
            result += " ";
        }
    }
    return result;
}
